// @ts-nocheck
// ===== หาคำที่ระบุ (เช่น "CG" ที่พิมพ์ในช่อง PRODUCTION NAME) ใน PLC (อ่านอย่างเดียว · กดครั้งละรอบ) =====
const HOST = "192.168.250.1", DA1 = 1, SA1 = 50;     // SA1 = เลขท้าย IP กล่อง
const WORD = "CG";                                    // คำที่ต้องการหา (พิมพ์บนจอ HMI ให้ตรงก่อนกด)
// พื้นที่ที่ค้น: [ชื่อ, รหัสพื้นที่ FINS, เริ่ม, ถึง]
const AREAS = [["D", 0x82, 0, 2999], ["W", 0xB1, 0, 511], ["H", 0xB2, 0, 511], ["CIO", 0xB0, 0, 511]];
const CHUNK = 200;

if (context.get("busy")) return null;
context.set("busy", true);
const sock = dgram.createSocket("udp4");
let sid = 0, pending = null;
sock.on("message", r => { if (pending && r.length >= 14 && r[9] === sid) pending(null, r); });
sock.on("error", e => pending && pending("socket " + e.code));
function read(area, start, count) {
    return new Promise(res => {
        sid = (sid + 1) & 0xFF;
        const t = setTimeout(() => pending && pending("timeout"), 1200);
        pending = (err, r) => {
            clearTimeout(t); pending = null;
            if (err) return res({ err });
            const ec = r.readUInt16BE(12);
            if (ec !== 0 && ec !== 0x0040) return res({ err: "end code 0x" + ec.toString(16) });
            const w = []; for (let k = 0; k < count; k++) w.push(r.readUInt16BE(14 + k * 2));
            res({ w });
        };
        sock.send(Buffer.from([0x80, 0, 0x02, 0, DA1, 0, 0, SA1, 0, sid, 0x01, 0x01, area,
            (start >> 8) & 0xFF, start & 0xFF, 0, (count >> 8) & 0xFF, count & 0xFF]), 9600, HOST, e => { if (e && pending) pending("send " + e.code); });
    });
}
const ch = c => (c >= 32 && c < 127 ? String.fromCharCode(c) : "·");
const txt = (w, swap) => { let a = (w >> 8) & 0xFF, b = w & 0xFF; if (swap) [a, b] = [b, a]; return ch(a) + ch(b); };

(async () => {
    sock.bind(0);
    const hits = [], errs = [];
    for (const [name, code, from, to] of AREAS) {
        const mem = {};
        for (let s = from; s <= to; s += CHUNK) {
            const n = Math.min(CHUNK, to - s + 1);
            node.status({ fill: "blue", shape: "dot", text: "กำลังอ่าน " + name + s + "…" });
            const r = await read(code, s, n);
            if (r.err) { errs.push(name + s + "-" + (s + n - 1) + ": " + r.err); continue; }
            r.w.forEach((v, k) => mem[s + k] = v);
        }
        for (const swap of [true, false]) {
            const ds = Object.keys(mem).map(Number).sort((a, b) => a - b);
            let line = "", idx = [];
            for (const d of ds) { line += txt(mem[d], swap); idx.push(d, d); }
            let pos = line.indexOf(WORD);
            while (pos >= 0) {
                const d = idx[pos];
                const around = []; for (let k = d; k < d + 6; k++) if (mem[k] !== undefined) around.push(txt(mem[k], swap));
                hits.push({ "ที่อยู่": name + d, "แบบ": swap ? "NJ (สลับ byte)" : "ปกติ", "ข้อความรอบๆ": around.join("").replace(/·/g, " ").trim(), "ค่าดิบ": "0x" + mem[d].toString(16).padStart(4, "0") });
                pos = line.indexOf(WORD, pos + 1);
            }
        }
    }
    try { sock.close(); } catch (e) {}
    context.set("busy", false);
    node.status({ fill: hits.length ? "green" : "yellow", shape: "dot", text: hits.length ? "เจอ \"" + WORD + "\" " + hits.length + " ที่" : "ไม่เจอ \"" + WORD + "\"" });
    node.send({ payload: { "คำที่หา": WORD, "เจอที่": hits.length ? hits : "ไม่เจอใน D0–2999 / W0–511 / H0–511 / CIO0–511", "อ่านไม่ได้": errs.length ? errs : undefined } });
})();
return null;
